use allowit::prelude::*;
/// Pay only destinations I approve.
pub fn execute(ctx: &AllowitContext) -> allowit::Result {
    allowit::destinations(ctx, ctx.params.get(allowit::DESTINATIONS))?;
    Ok(())
}

